/**
 * The user's notifications across every workspace, newest first (20 at
 * first), in an uncontrolled `NotificationList` that handles mark-read
 * and "Load more" itself.
 */

import type { Metadata } from "next";
import { Suspense } from "react";
import { getTranslations } from "next-intl/server";

import { getNotifications } from "@/actions/notifications";
import { NotificationList } from "@/components/notifications/notification-list";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("notifications");
  return { title: t("page.title") };
}

export default async function NotificationsPage() {
  const t = await getTranslations("notifications");

  return (
    <div className="container mx-auto max-w-2xl space-y-8 px-4 py-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>{t("page.subtitle")}</PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      <Suspense fallback={null}>
        <NotificationsSection />
      </Suspense>
    </div>
  );
}

async function NotificationsSection() {
  const result = await getNotifications();

  if (!result.success) {
    return (
      <div className="rounded-lg border p-6 text-sm text-destructive">
        {result.error}
      </div>
    );
  }

  return (
    <div className="rounded-lg border">
      <NotificationList notifications={result.data} variant="full" />
    </div>
  );
}

"use client";

/**
 * Bell with an unread badge that opens a dropdown of recent
 * notifications. Nothing mounts it for you: put it in the shell, e.g.
 * through `shellConfig.headerRight`.
 *
 * With no props it fetches on mount. Pass `initialCount` and
 * `initialNotifications` from a server component for a faster first
 * paint; it then skips that fetch.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";
import { Bell } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SwapText } from "@/components/ui/ai-motion";
import { Link } from "@/i18n/navigation";

import { useNotifications } from "@/hooks/use-notifications";
import type { NotificationData } from "@/actions/notifications";
import { NotificationList } from "./notification-list";

export interface NotificationBellProps {
  initialCount?: number;
  initialNotifications?: NotificationData[];
  /** Where "View all" links. Matches this item's own installed page. */
  notificationsHref?: string;
}

export function NotificationBell({
  initialCount,
  initialNotifications,
  notificationsHref = "/notifications",
}: NotificationBellProps) {
  const [isOpen, setIsOpen] = useState(false);
  const t = useTranslations("notifications");

  const { notifications, unreadCount, markRead, markAllRead } =
    useNotifications({
      initialCount,
      initialNotifications,
      // Skip polling while the user is reading the dropdown.
      paused: isOpen,
    });

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger
        render={
          <Button
            variant="ghost"
            size="icon"
            className="relative"
            aria-label={
              unreadCount > 0
                ? t("bell.ariaLabelUnread", { count: unreadCount })
                : t("bell.ariaLabel")
            }
          />
        }
      >
        <Bell className="size-5" />
        {unreadCount > 0 && (
          <span className="absolute -right-0.5 -top-0.5 flex h-4.5 min-w-4.5 items-center justify-center rounded-full bg-destructive px-1 text-xs text-destructive-foreground">
            {/* A new count rolls in rather than replacing the old one. */}
            <SwapText value={String(unreadCount)}>
              {unreadCount > 99 ? "99+" : unreadCount}
            </SwapText>
          </span>
        )}
      </PopoverTrigger>
      <PopoverContent align="end" className="w-96 p-0">
        <NotificationList
          notifications={notifications}
          variant="compact"
          onMarkRead={markRead}
          onMarkAllRead={markAllRead}
          onNavigate={() => setIsOpen(false)}
          footer={
            <Link
              href={notificationsHref}
              className="block border-t px-4 py-2 text-center text-sm text-muted-foreground transition-colors hover:text-foreground"
              onClick={() => setIsOpen(false)}
            >
              {t("bell.viewAll")}
            </Link>
          }
        />
      </PopoverContent>
    </Popover>
  );
}

"use client";

/**
 * The notification rows, a header with "Mark all read", and an empty
 * state. Two modes:
 *
 * - Controlled (the bell, `variant="compact"`): pass `onMarkRead` and
 *   `onMarkAllRead` from `useNotifications` so clicks keep its unread
 *   count in sync.
 * - Uncontrolled (the page, `variant="full"`): omit them and the list
 *   keeps its own optimistic state, calls the server actions itself and
 *   owns "Load more", which re-fetches with a larger limit (up to 100).
 */

import { useState, useTransition, type ReactNode } from "react";
import { useTranslations } from "next-intl";
import { Bell } from "lucide-react";

import { useRouter } from "@/i18n/navigation";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { AnimatedList, AnimatedListItem } from "@/components/ui/animated-list";
import { NotificationStack } from "@/components/ui/notification-stack";

import {
  getNotifications,
  markAllNotificationsRead,
  markNotificationRead,
  type NotificationData,
} from "@/actions/notifications";
import {
  NotificationItem,
  notificationIcon,
  RelativeTime,
} from "./notification-item";

const PAGE_SIZE = 20;
const MAX_LIMIT = 100;

export interface NotificationListProps {
  notifications: NotificationData[];
  variant?: "compact" | "full";
  /** Rendered below the list, e.g. a "View all" link in the bell dropdown. */
  footer?: ReactNode;
  /** Pass both to run this list in controlled mode — see file doc comment. */
  onMarkRead?: (id: string) => void;
  onMarkAllRead?: () => void;
  /** Called after opening a notification's link — the bell closes its dropdown. */
  onNavigate?: () => void;
}

export function NotificationList({
  notifications,
  variant = "full",
  footer,
  onMarkRead,
  onMarkAllRead,
  onNavigate,
}: NotificationListProps) {
  const t = useTranslations("notifications");
  const router = useRouter();
  const controlled = onMarkRead !== undefined;

  const [ownedItems, setOwnedItems] = useState(notifications);
  const [limit, setLimit] = useState(PAGE_SIZE);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [, startTransition] = useTransition();

  const items = controlled ? notifications : ownedItems;
  const hasUnread = items.some((n) => !n.isRead);
  const canLoadMore =
    variant === "full" &&
    !controlled &&
    items.length >= limit &&
    limit < MAX_LIMIT;

  function handleMarkRead(id: string) {
    if (controlled) {
      onMarkRead?.(id);
      return;
    }
    setOwnedItems((prev) =>
      prev.map((n) => (n.id === id ? { ...n, isRead: true } : n))
    );
    startTransition(async () => {
      await markNotificationRead(id);
    });
  }

  function handleMarkAllRead() {
    if (controlled) {
      onMarkAllRead?.();
      return;
    }
    setOwnedItems((prev) => prev.map((n) => ({ ...n, isRead: true })));
    startTransition(async () => {
      await markAllNotificationsRead();
    });
  }

  function handleLoadMore() {
    const nextLimit = Math.min(limit + PAGE_SIZE, MAX_LIMIT);
    setIsLoadingMore(true);
    startTransition(async () => {
      const result = await getNotifications(nextLimit);
      if (result.success) {
        setOwnedItems(result.data);
        setLimit(nextLimit);
      }
      setIsLoadingMore(false);
    });
  }

  // Rows rise in one after another; one that arrives later rises alone.
  const rows = items.map((notification) => (
    <AnimatedListItem as="div" key={notification.id}>
      <NotificationItem
        notification={notification}
        onMarkRead={handleMarkRead}
      />
    </AnimatedListItem>
  ));

  return (
    <div className="flex flex-col">
      {/* The title shows only in the bell dropdown; the page has its
          own. The row is dropped when it would hold neither the title
          nor the mark-all action. */}
      {(variant === "compact" || hasUnread) && (
        <>
          <div
            className={`flex items-center px-4 py-3 ${
              variant === "compact" ? "justify-between" : "justify-end"
            }`}
          >
            {variant === "compact" ? (
              <h3 className="text-sm font-semibold">{t("list.title")}</h3>
            ) : null}
            {hasUnread && (
              <button
                type="button"
                className="text-sm text-muted-foreground transition-colors hover:text-foreground"
                onClick={handleMarkAllRead}
              >
                {t("list.markAllRead")}
              </button>
            )}
          </div>
          <Separator />
        </>
      )}

      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-2 py-12 text-center text-muted-foreground">
          <Bell className="size-8" />
          <p className="text-sm">{t("list.emptyTitle")}</p>
          <p className="max-w-xs text-xs">{t("list.emptyDescription")}</p>
        </div>
      ) : variant === "compact" && hasUnread ? (
        // The dropdown is an inbox of what is new: unread notifications
        // fanned into a stack that springs apart on hover. Opening one
        // or dismissing it marks it read, and it leaves the stack.
        <div className="p-3">
          <NotificationStack
            items={items
              .filter((n) => !n.isRead)
              .map((n) => {
                const { Icon, color } = notificationIcon(n.type);
                return {
                  id: n.id,
                  title: n.title,
                  description: n.message,
                  time: <RelativeTime iso={n.createdAt} />,
                  icon: <Icon className={`size-4 ${color}`} />,
                  unread: true,
                };
              })}
            onItemClick={(item) => {
              handleMarkRead(item.id);
              const href = items.find((n) => n.id === item.id)?.href;
              if (href) {
                router.push(href);
                onNavigate?.();
              }
            }}
            onDismiss={(item) => handleMarkRead(item.id)}
            labels={{
              expand: t("stack.expand"),
              collapse: t("stack.collapse"),
              empty: t("stack.empty"),
              dismiss: t("stack.dismiss"),
              list: (count) => t("stack.list", { count }),
              unread: t("stack.unread"),
            }}
          />
        </div>
      ) : variant === "compact" ? (
        // `flex flex-col`: the viewport's percentage height resolves to
        // `auto` against a capped root, and the rows would spill past
        // the cap instead of scrolling.
        <ScrollArea className="flex max-h-100 flex-col">
          <AnimatedList as="div" className="flex flex-col">
            {rows}
          </AnimatedList>
        </ScrollArea>
      ) : (
        <AnimatedList as="div" className="flex flex-col">
          {rows}
        </AnimatedList>
      )}

      {footer}

      {canLoadMore && (
        <div className="border-t p-3 text-center">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleLoadMore}
            disabled={isLoadingMore}
          >
            {isLoadingMore ? t("list.loading") : t("list.loadMore")}
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * A single notification row: type icon, unread dot, title/message,
 * relative timestamp. Clicking an unread row marks it read; a row with
 * an `href` is also a link there.
 */

import { useEffect, useState } from "react";
import { useFormatter } from "next-intl";
import {
  AlertTriangle,
  Bell,
  CheckCircle,
  Clock,
  CreditCard,
  UserPlus,
  type LucideIcon,
} from "lucide-react";

import { Link } from "@/i18n/navigation";
import type { NotificationData } from "@/actions/notifications";

export interface NotificationItemProps {
  notification: NotificationData;
  onMarkRead: (id: string) => void;
}

/**
 * Relative timestamp that can't cause a hydration mismatch: the server
 * (and the first client render) show a locale-formatted absolute date,
 * and an effect swaps in the relative form once mounted — `Date.now()`
 * during render would differ between server and client.
 */
export function RelativeTime({ iso }: { iso: string }) {
  const format = useFormatter();
  const [now, setNow] = useState<Date | null>(null);
  useEffect(() => setNow(new Date()), []);
  const date = new Date(iso);
  return (
    <>
      {now
        ? format.relativeTime(date, now)
        : format.dateTime(date, { dateStyle: "medium" })}
    </>
  );
}

/**
 * Icon and colour for a built-in notification `type`; any other type
 * falls back to a plain bell.
 */
export function notificationIcon(type: string): {
  Icon: LucideIcon;
  color: string;
} {
  switch (type) {
    case "quota_warning_80":
      return { Icon: AlertTriangle, color: "text-warning" };
    case "quota_warning_100":
      return { Icon: AlertTriangle, color: "text-destructive" };
    case "trial_warning_20":
      return { Icon: Clock, color: "text-warning" };
    case "trial_depleted":
      return { Icon: Clock, color: "text-destructive" };
    case "payment_failed":
      return { Icon: CreditCard, color: "text-destructive" };
    case "team_member_joined":
      return { Icon: UserPlus, color: "text-success" };
    case "subscription_confirmed":
      return { Icon: CheckCircle, color: "text-success" };
    default:
      return { Icon: Bell, color: "text-muted-foreground" };
  }
}

export function NotificationItem({
  notification,
  onMarkRead,
}: NotificationItemProps) {
  const { id, type, title, message, isRead, createdAt, href } = notification;
  const { Icon, color } = notificationIcon(type);

  function handleClick() {
    if (!isRead) onMarkRead(id);
  }

  const rowClassName =
    "flex w-full items-start gap-3 px-4 py-3 text-left transition-colors hover:bg-accent/50";

  const content = (
    <>
      <span className="mt-2 flex-shrink-0" aria-hidden>
        <span
          className={`block size-2 rounded-full ${isRead ? "bg-transparent" : "bg-primary"}`}
        />
      </span>

      <span className={`mt-0.5 flex-shrink-0 ${color}`} aria-hidden>
        <Icon className="size-4" />
      </span>

      <span className="min-w-0 flex-1">
        <span className="block truncate text-sm font-medium">{title}</span>
        <span className="block line-clamp-2 text-sm text-muted-foreground">
          {message}
        </span>
      </span>

      <span className="flex-shrink-0 text-xs text-muted-foreground">
        <RelativeTime iso={createdAt} />
      </span>
    </>
  );

  if (href) {
    return (
      <Link href={href} className={rowClassName} onClick={handleClick}>
        {content}
      </Link>
    );
  }

  return (
    <button type="button" className={rowClassName} onClick={handleClick}>
      {content}
    </button>
  );
}

"use client";

/**
 * The bell's unread count and recent list, polled every 60s and paused
 * while `paused` is true. Mutations are optimistic.
 *
 * Pass `initialCount`/`initialNotifications` when a server component
 * already fetched them; omit both and the hook fetches on mount.
 */

import { useCallback, useEffect, useRef, useState, useTransition } from "react";

import {
  getUnreadCount,
  getUnreadNotifications,
  markAllNotificationsRead,
  markNotificationRead,
  type NotificationData,
} from "@/actions/notifications";

const POLL_INTERVAL_MS = 60_000;
const RECENT_LIMIT = 10;

export interface UseNotificationsOptions {
  initialCount?: number;
  initialNotifications?: NotificationData[];
  /** Skip the next poll tick while true (e.g. the bell dropdown is open). */
  paused?: boolean;
}

export interface UseNotificationsResult {
  notifications: NotificationData[];
  unreadCount: number;
  isPending: boolean;
  markRead: (id: string) => void;
  markAllRead: () => void;
  refresh: () => void;
}

export function useNotifications(
  options: UseNotificationsOptions = {}
): UseNotificationsResult {
  const [notifications, setNotifications] = useState<NotificationData[]>(
    options.initialNotifications ?? []
  );
  const [unreadCount, setUnreadCount] = useState(options.initialCount ?? 0);
  const [isPending, startTransition] = useTransition();

  const pausedRef = useRef(options.paused ?? false);
  pausedRef.current = options.paused ?? false;

  // Only ever read once: whether the caller handed us a starting point
  // decides if we fetch on mount, independent of later prop changes.
  const hadInitialData = useRef(options.initialNotifications !== undefined);

  const refresh = useCallback(() => {
    startTransition(async () => {
      const [countResult, listResult] = await Promise.all([
        getUnreadCount(),
        getUnreadNotifications(RECENT_LIMIT),
      ]);
      if (countResult.success) setUnreadCount(countResult.data);
      if (listResult.success) setNotifications(listResult.data);
    });
  }, []);

  useEffect(() => {
    // Runs once on mount; `refresh` is a stable useCallback.
    if (!hadInitialData.current) refresh();
  }, [refresh]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (!pausedRef.current) refresh();
    }, POLL_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [refresh]);

  const markRead = useCallback((id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, isRead: true } : n))
    );
    setUnreadCount((prev) => Math.max(0, prev - 1));
    startTransition(async () => {
      await markNotificationRead(id);
    });
  }, []);

  const markAllRead = useCallback(() => {
    setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));
    setUnreadCount(0);
    startTransition(async () => {
      await markAllNotificationsRead();
    });
  }, []);

  return {
    notifications,
    unreadCount,
    isPending,
    markRead,
    markAllRead,
    refresh,
  };
}

"use server";

/**
 * Notification actions over `@intelligo-dev/core/notifications`.
 *
 * User-scoped, not workspace-scoped: `requireAuth()`, not
 * `requireWorkspace()`, because notifications span every workspace a user
 * belongs to and are shown in one list.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import { requireAuth } from "@intelligo-dev/auth";
import {
  getNotifications as coreGetNotifications,
  getUnreadNotifications as coreGetUnreadNotifications,
  getNotificationCount,
  markAsRead,
  markAllAsRead,
} from "@intelligo-dev/core/notifications";

export type ActionResult<T> =
  { success: true; data: T } | { success: false; error: string };

export type NotificationData = {
  id: string;
  type: string;
  title: string;
  message: string;
  isRead: boolean;
  /** ISO string — Dates don't cross the server action boundary as-is. */
  createdAt: string;
  /**
   * Optional deep link, read from `metadata.href`: pass
   * `metadata: { href: "/billing" }` to `createNotification()`. The table
   * has no link column, and the built-in triggers set none. `null` when
   * absent.
   */
  href: string | null;
};

// The core reads take a `limit`, not an offset or cursor, so "Load more"
// re-fetches with a larger limit, up to the ceiling.
const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const NOTIFICATIONS_PATH = "/notifications";

type CoreNotification = Awaited<
  ReturnType<typeof coreGetNotifications>
>[number];

function clampLimit(limit: number): number {
  return Math.min(Math.max(Math.trunc(limit) || DEFAULT_LIMIT, 1), MAX_LIMIT);
}

function toNotificationData(row: CoreNotification): NotificationData {
  const href =
    typeof row.metadata?.href === "string" ? row.metadata.href : null;

  return {
    id: row.id,
    type: row.type,
    title: row.title,
    message: row.message,
    isRead: row.isRead,
    createdAt: row.createdAt.toISOString(),
    href,
  };
}

/**
 * The reader gets the translated fallback; the error itself goes to the
 * server log. `Error#message` can carry internals (SQL, hostnames).
 */
function errorMessage(error: unknown, fallback: string): string {
  console.error("[notifications]", error);
  return fallback;
}

/**
 * All notifications (read and unread) for the current user, newest first.
 * Powers the full notifications page; `limit` grows for "Load more".
 */
export async function getNotifications(
  limit: number = DEFAULT_LIMIT
): Promise<ActionResult<NotificationData[]>> {
  try {
    const { user } = await requireAuth();
    const rows = await coreGetNotifications(user.id, clampLimit(limit));
    return { success: true, data: rows.map(toNotificationData) };
  } catch (error) {
    const t = await getTranslations("notifications");
    return {
      success: false,
      error: errorMessage(error, t("errors.loadNotifications")),
    };
  }
}

/**
 * Unread notifications for the current user, newest first. Powers the
 * bell dropdown's recent list.
 */
export async function getUnreadNotifications(
  limit: number = DEFAULT_LIMIT
): Promise<ActionResult<NotificationData[]>> {
  try {
    const { user } = await requireAuth();
    const rows = await coreGetUnreadNotifications(user.id, clampLimit(limit));
    return { success: true, data: rows.map(toNotificationData) };
  } catch (error) {
    const t = await getTranslations("notifications");
    return {
      success: false,
      error: errorMessage(error, t("errors.loadUnreadNotifications")),
    };
  }
}

/** Unread count for the current user. Powers the bell badge. */
export async function getUnreadCount(): Promise<ActionResult<number>> {
  try {
    const { user } = await requireAuth();
    const count = await getNotificationCount(user.id);
    return { success: true, data: count };
  } catch (error) {
    const t = await getTranslations("notifications");
    return {
      success: false,
      error: errorMessage(error, t("errors.loadUnreadCount")),
    };
  }
}

/**
 * Marks one notification as read. The update is scoped to
 * `(notificationId, userId)`, so it cannot touch another user's.
 */
export async function markNotificationRead(
  notificationId: string
): Promise<ActionResult<undefined>> {
  try {
    const { user } = await requireAuth();
    await markAsRead(notificationId, user.id);
    revalidatePath(NOTIFICATIONS_PATH);
    return { success: true, data: undefined };
  } catch (error) {
    const t = await getTranslations("notifications");
    return {
      success: false,
      error: errorMessage(error, t("errors.markRead")),
    };
  }
}

/** Mark every unread notification as read for the current user. */
export async function markAllNotificationsRead(): Promise<
  ActionResult<undefined>
> {
  try {
    const { user } = await requireAuth();
    await markAllAsRead(user.id);
    revalidatePath(NOTIFICATIONS_PATH);
    return { success: true, data: undefined };
  } catch (error) {
    const t = await getTranslations("notifications");
    return {
      success: false,
      error: errorMessage(error, t("errors.markAllRead")),
    };
  }
}

{
  "page": {
    "title": "Notifications",
    "subtitle": "Quota, billing, and team updates for your account, across every workspace."
  },
  "list": {
    "title": "Notifications",
    "markAllRead": "Mark all read",
    "emptyTitle": "No notifications yet",
    "emptyDescription": "Quota, billing, and team updates will show up here.",
    "loading": "Loading…",
    "loadMore": "Load more"
  },
  "bell": {
    "ariaLabel": "Notifications",
    "ariaLabelUnread": "Notifications ({count} unread)",
    "viewAll": "View all"
  },
  "errors": {
    "loadNotifications": "Failed to load notifications",
    "loadUnreadNotifications": "Failed to load unread notifications",
    "loadUnreadCount": "Failed to load unread count",
    "markRead": "Failed to mark notification as read",
    "markAllRead": "Failed to mark all notifications as read"
  },
  "stack": {
    "expand": "Show all",
    "collapse": "Show less",
    "empty": "You're all caught up",
    "dismiss": "Mark as read",
    "list": "{count, plural, one {# new notification} other {# new notifications}}",
    "unread": "Unread"
  }
}

"use client";

/**
 * Error boundary for the notifications page. Renders `RouteError` from
 * the `route-error` item, which must be installed too.
 */

import { RouteError } from "@/components/shared/route-error";

export default function SegmentError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return <RouteError error={error} reset={reset} scope="notifications" />;
}
